/// <summary>
/// AVA_007513_TransferJournalsDepreciation
/// </summary>
internal final class AVATransferCalcDepreciationUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField df_dateCode, df_fromDate, df_toDate, df_journalNameId, df_postingDate;

}

Method.Source:
public void postBuild()
{
    super();

    df_journalNameId = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(AVATransferCalcDepreciationContract, parmJournalName));
    df_journalNameId.value(AssetParameters::find().AVACalculationJournalNameId);
    df_journalNameId.allowEdit(false);

    df_postingDate = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(AVATransferCalcDepreciationContract,parmPostingDate));

    df_dateCode = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(AVATransferCalcDepreciationContract, parmPeriodCode));
    df_dateCode.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(AVATransferCalcDepreciationUIBuilder, dateCodeModified), this);

    df_fromDate = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(AVATransferCalcDepreciationContract, parmFromDate));

    df_toDate = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(AVATransferCalcDepreciationContract, parmToDate));
}

/// <summary>
/// AVA_007513_TransferJournalsDepreciation
/// </summary>
/// <param name = "_formControl">FormStringControl</param>
/// <returns>Boolean</returns>
public boolean dateCodeModified(FormStringControl _formControl)
{
    boolean             ret;
    LedgerPeriodCode    ledgerPeriodCode; 
    FromDate            fromDate;
    ToDate              toDate;

    ret = _formControl.modified();

    if (ret)
    {
        if (_formControl.valueStr())
        {
            ledgerPeriodCode = LedgerPeriodCode::find(_formControl.valueStr());
            if (ledgerPeriodCode)
            {
                fromDate = ledgerPeriodCode.fromDate();
                toDate = ledgerPeriodCode.toDate();
            }
        }

        df_fromDate.value(fromDate);
        df_toDate.value(toDate);
    }

    return ret;
}
